import{z as i,x as s,o as r,c as A,q as o,j as t,D as a,d as E,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"MemOS 记忆操作系统","description":"","frontmatter":{"title":"MemOS 记忆操作系统","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/memos-os.md","filePath":"llm/memos-os.md","lastUpdated":1791413859000}'),M={name:"llm/memos-os.md"};function p(d,e,B,h,c,u){const m=s("Mermaid");return r(),A("div",null,[e[2]||(e[2]=o('<h1 id="memos-记忆操作系统" tabindex="-1">MemOS 记忆操作系统 <a class="header-anchor" href="#memos-记忆操作系统" aria-label="Permalink to &quot;MemOS 记忆操作系统&quot;">​</a></h1><div class="epigraph"><p>把明文、激活与参数三种记忆收成可调度的系统资源，而不是把 RAG 当成无生命周期的临时补丁。</p><footer>—— Li 等，MemOS: A Memory OS for AI System，arXiv:2507.03724</footer></div><p><a href="/llm/memgpt">MemGPT</a> 把固定窗口当 RAM、外部库当磁盘，由模型经函数换页；那是<strong>工具级</strong>记忆管理。<a href="/llm/amem-agent-memory">A-MEM</a> 让笔记结构自己演化，仍停在文本库。Li、Song、Xi、Xiong 等人的 <strong>MemOS</strong> 把问题再抬一层：明文记忆、激活记忆（KV / 隐状态）与参数记忆（权重、LoRA、编辑）本是异构对象，却长期没有统一的表示、调度与治理。系统把最小单元做成 <strong>MemCube</strong>——载荷加元数据——并按操作系统分层：接口、操作、基础设施。评测主场是 LoCoMo；对照 LangMem、Zep、OpenAI-Memory 与 Mem0。本篇写资源抽象与生命周期，不把「记忆操作系统」写成已替代注意力核。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主流 LLM 把知识压进参数，更新贵、难解释；RAG 把知识留在库外，推理时临时拼进窗口，却没有版本、出处与过期策略。一次检索成功，不保证下次同一事实仍被同一路径召回；法规更新后新旧条文可能并存。作者把这四类缺口写清楚：长程依赖与窗口二次代价、知识演化缺少时间轴、个性化跨会话丢失、以及跨产品「记忆孤岛」。缺的不是再一个向量库，而是把记忆当成 CPU / 内存那样的<strong>一等资源</strong>。</p><p>论文把 LLM 记忆沿「显式 / 隐式 × 短时 / 长时」铺开：参数与适配器是隐式长时；KV 与隐状态是隐式短时；prompt 是显式短时；RAG / 图检索是显式长时。工具期（EasyEdit、Mem0、Letta）已提供增删改接口，但仍像系统调用没有操作系统：没有调度、分层、权限与异常处理。MemOS 自称进入「系统治理」阶段——这句话要以模块是否真正调度异构记忆来检验，不能只看产品名。</p><h3 id="三种记忆为何必须能互相转化" tabindex="-1">三种记忆为何必须能互相转化 <a class="header-anchor" href="#三种记忆为何必须能互相转化" aria-label="Permalink to &quot;三种记忆为何必须能互相转化&quot;">​</a></h3><p>明文适合可编辑事实与个性化；激活适合多轮连贯与低延迟复用；参数适合稳定能力（摘要专家、法务风格）。高频明文若永远走检索，prefill 会重复付钱；过时参数若不能卸回明文，就只能全量微调。因此需要策略驱动的路径：明文 → 激活（热 KV / 模板）、明文或激活 → 参数（蒸馏、适配器）、冷参数 → 明文（外置以便修订）。没有这条闭环，分层只是分类学。</p><p><span class="marginnote">MemCube 可以理解成「贴了标签的记忆集装箱」：箱内装记忆内容（一段明文、一份 KV、一个 LoRA 增量），箱外贴元数据（来源、TTL、谁能读、访问频率）。调度器不打开箱子就能决定它该放热层还是冷仓。</span></p><p><span class="marginnote">MemOS 把 Memory3 的「参数与检索之间再加一层显式记忆」扩成系统：MemCube 可组合、可迁移、可融合。引用实验数字以 arXiv:2507.03724 的 LoCoMo 设定为准，不要把后续产品默认提示写回这篇表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MemCube 分载荷与元数据。元数据三类：描述性标识（时间戳、来源签名、语义类型）、治理属性（读写范围、TTL、优先级、合规标签）、行为指标（访问频率与近因、上下文指纹、版本链）。调度器据此决定热 / 冷、以及跨类型迁移。架构三层。<strong>接口层</strong>：MemReader 把自然语言解析成带时间窗与意图的 MemoryCall；Memory API 统一查询、写入、更新、迁移；Pipeline 把「检索 → 增强 → 更新 → 归档」串成可回滚的工作流。<strong>操作层</strong>：MemOperator 做标签、图与分层索引；MemScheduler 按任务选明文 / 激活 / 参数并决定注入顺序；MemLifecycle 跟踪 Generated → Activated → Merged → Archived（及过期）。<strong>基础设施层</strong>：MemGovernance 做 ACL 与审计，MemVault 管多后端仓库，MemLoader / Dumper 做导入导出，MemStore 做受控发布订阅。</p><p>评测用 GPT-4o-mini 为统一骨干，在 LoCoMo 上比 LLM-Judge。MemOS-0630 整体 Judge <strong>73.31</strong>，高于 Mem0 的 64.57、OpenAI-Memory 的 52.75、LangMem 的 55.76、Zep 的 41.62。时间推理一项 MemOS 为 <strong>73.21</strong>，Mem0 为 52.34，差距最大；多跳 64.30 对 Mem0 的 58.75。检索配置约 Top-K=20、记忆段约 1.5k–1.6k token。这是记忆系统对照，不是改 Transformer 层。</p>',13)),(r(),t(l,null,{default:a(()=>[n(m,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%20%2F%20%E4%BB%BB%E5%8A%A1%E8%BE%93%E5%85%A5%22%5D%20--%3E%20R%5B%22MemReader%20%E2%86%92%20MemoryCall%22%5D%0A%20%20R%20--%3E%20OP%5B%22MemOperator%20%E7%B4%A2%E5%BC%95%E4%B8%8E%E5%80%99%E9%80%89%22%5D%0A%20%20OP%20--%3E%20SCH%5B%22MemScheduler%20%E9%80%89%E7%B1%BB%E5%9E%8B%E4%B8%8E%E6%B3%A8%E5%85%A5%22%5D%0A%20%20SCH%20--%3E%20LC%5B%22MemLifecycle%20%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20LC%20--%3E%20V%5B%22MemVault%20%2F%20MemGovernance%22%5D%0A%20%20V%20--%3E%20LLM%5B%22%E6%8E%A8%E7%90%86%EF%BC%9A%E6%98%8E%E6%96%87%20%2F%20KV%20%2F%20%E5%8F%82%E6%95%B0%E6%8F%92%E4%BB%B6%22%5D%0A%20%20LLM%20--%3E%20C%5B%22MemCube%20%E5%86%99%E5%9B%9E%22%5D%0A%20%20C%20--%3E%20OP%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p><span class="marginnote">数字实例：总体 Judge 73.31 对 64.57，体感是「每 10 题错 3.5 个变成错 2.7 个」；真正拉开差距的是时间推理 73.21 对 52.34——「这件事是上个月还是去年」这类时间轴问题，恰是普通向量检索最弱的地方。</span></p><h3 id="生命周期不是-lru-的别名" tabindex="-1">生命周期不是 LRU 的别名 <a class="header-anchor" href="#生命周期不是-lru-的别名" aria-label="Permalink to &quot;生命周期不是 LRU 的别名&quot;">​</a></h3><p>Generated 是刚抽出的摘要；被后续任务引用才进入 Activated；语义重叠触发 Merged；长期不用进 Archived。Time Machine 允许把归档版本拉回做反事实，而不覆盖冻结的合规副本。医疗场景里诊疗摘要对医护全可见、对患者部分可见，靠 ACL 与脱敏，不是靠「再检索一次」。这与 MemGPT 的工作记忆 replace 不同：后者改窗口前缀，前者改可审计对象的状态。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>调度的机制是类型感知加载。连贯性重的多轮偏向 KV 路径，减少重复 prefill；程序性专家流偏向参数模块；即时事实走明文插入。行为指标让系统感知「这份记忆现在值多少」：高频明文可预变成激活模板；跨会话稳定的规则可蒸馏进 LoRA 式能力块；低热 KV 降级回明文进冷仓。版本链支持冲突消解与回滚，否则融合会把错误事实固化成参数。</p>',5)),(r(),t(l,null,{default:a(()=>[n(m,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E6%98%8E%E6%96%87%E8%AE%B0%E5%BF%86%EF%BC%9A%E5%8F%AF%E7%BC%96%E8%BE%91%E4%BA%8B%E5%AE%9E%22%5D%20--%3E%7C%22%E9%AB%98%E9%A2%91%EF%BC%9A%E9%A2%84%E5%8F%98%E6%88%90%E6%A8%A1%E6%9D%BF%22%7C%20ACT%5B%22%E6%BF%80%E6%B4%BB%E8%AE%B0%E5%BF%86%EF%BC%9A%E7%83%AD%20KV%20%2F%20%E9%9A%90%E7%8A%B6%E6%80%81%22%5D%0A%20%20ACT%20--%3E%7C%22%E4%BD%8E%E7%83%AD%E9%99%8D%E7%BA%A7%22%7C%20PT%0A%20%20PT%20--%3E%7C%22%E8%92%B8%E9%A6%8F%20%2F%20%E9%80%82%E9%85%8D%E5%99%A8%22%7C%20PM%5B%22%E5%8F%82%E6%95%B0%E8%AE%B0%E5%BF%86%EF%BC%9A%E6%9D%83%E9%87%8D%20%2F%20LoRA%22%5D%0A%20%20PM%20--%3E%7C%22%E8%BF%87%E6%97%B6%E5%8F%82%E6%95%B0%E5%A4%96%E7%BD%AE%E5%9B%9E%E5%86%99%22%7C%20PT%0A%20%20S%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%EF%BC%9A%E6%8C%89%E8%AE%BF%E9%97%AE%E9%A2%91%E7%8E%87%E4%B8%8E%E8%BF%91%E5%9B%A0%22%5D%20-.-%3E%20PT%0A%20%20S%20-.-%3E%20ACT%0A%20%20S%20-.-%3E%20PM%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p><span class="marginnote">常见误区：把记忆生命周期当成缓存 LRU。MemOS 的状态机（Generated → Activated → Merged → Archived）还带 ACL、版本链与合规冻结副本——它治理的是「谁在什么时候能看哪一版」，不只是「谁最近没被用到」。</span></p><p>与 <a href="/llm/memgpt">MemGPT</a> / Letta 的差别在抽象层：Letta 管窗口放置与函数换页，MemOS 还声称调度 KV 与参数增量。工程上两者可叠——Letta 当进程内 RAM 管理，MemOS 当跨会话、跨类型的仓库——但那是集成，不是 2507.03724 的默认实验。与 A-MEM 的差别在演化对象：A-MEM 演化笔记元数据以改检索分布；MemOS 演化的是记忆形态本身。</p><p><span class="marginnote">Judge 分数依赖 GPT-4o-mini 与提示；F1 / ROUGE 上 MemOS 并非每一列都高于 Mem0（单跳 F1 45.55 对 47.26）。引用时分列，不要只报总体 73.31。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="操作系统类比的硬边界" tabindex="-1">操作系统类比的硬边界 <a class="header-anchor" href="#操作系统类比的硬边界" aria-label="Permalink to &quot;操作系统类比的硬边界&quot;">​</a></h3><p>传统 OS 的缺页由 MMU 保证；MemOS 的「该取哪块」仍是启发式调度加 LLM 解析。MemReader 抽错时间窗，后续全错。参数蒸馏不可逆地损失可编辑性；明文升 KV 会把隐私事实写进难以审计的缓存。多租户必须在 MemCube 上做隔离，而不能假定向量库天然分租户。论文主实验是对话 QA，不是把任意 LoRA 热插拔到生产集群。</p><p>短版本 arXiv:2505.22101 把同一套哲学收成 MAG（Memory-Augmented Generation）提纲；引用架构细节以 2507.03724 为准。代码与站点：github.com/MemTensor/MemOS、memos.openmem.net。不要把后续商业控制台的默认策略写回这篇表。</p><p><span class="marginnote">出处：Li, Song, Xi, Wang, Tang, Niu 等（MemTensor / 上交 / 高研院等），<em>MemOS: A Memory OS for AI System</em>，arXiv:2507.03724。LoCoMo 见 Maharana 等。基线含 Mem0、Zep、LangMem、OpenAI-Memory。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MemOS 把明文、激活、参数记忆统一成可调度资源，MemCube 是带治理元数据的最小单元。</li><li>三层：接口（Reader / API）、操作（Operator / Scheduler / Lifecycle）、基础设施（Governance / Vault）。</li><li>跨类型迁移把高频知识内化、把过时参数外置；生命周期可审计。</li><li>LoCoMo 上 MemOS-0630 总体 Judge 73.31，时间推理相对 Mem0 优势最大。</li><li>「操作系统」管的是放置与治理，不是无限注意力。</li><li>出处：Li et al.，arXiv:2507.03724。</li></ul>',10))])}const L=i(M,[["render",p]]);export{g as __pageData,L as default};
